"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["24219"],{77480(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.ordem_duplicada_na_origem","status":422,"titulo":"A mesma origem tem mais de um destino na mesma posi\xe7\xe3o de ordem"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.ordem_duplicada_na_origem","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["Duas ou mais posi\xe7\xf5es da cascata com o mesmo `modalidadeOrigemCodigo`\\ndeclaram o mesmo valor de `ordem`. A ordem decide a sequ\xeancia em que os\\ndestinos daquela origem s\xe3o tentados \u2014 repetida, n\xe3o h\xe1 como saber qual\\ndestino vem primeiro.","Esta confer\xeancia, e as duas causas irm\xe3s que compartilham a mesma passada\\nsobre cada origem \u2014\\n[`ordem_nao_contigua`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_nao_contigua)\\ne\\n[`destino_duplicado`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.destino_duplicado)\\n\u2014, s\xf3 rodam depois de todos os itens de `destinos` j\xe1 terem sido\\nconstru\xeddos individualmente com sucesso (ver\\n[`codigo_invalido`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.codigo_invalido)\\ne\\n[`ordem_invalida`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_invalida)),\\nj\xe1 que dependem de agrupar os destinos por origem. Se qualquer item\\nfalhar, este c\xf3digo n\xe3o roda \u2014 em vez dele, o lote acumula os erros de\\nitem mais fallback/limites, nunca as tr\xeas causas por origem.","Quando roda, acumula (ADR-0125): a mesma origem pode reprovar as tr\xeas\\ncausas por origem ao mesmo tempo (ordem duplicada, sequ\xeancia n\xe3o cont\xedgua\\ne destino repetido n\xe3o se excluem entre si), e origens diferentes com\\nproblemas diferentes contribuem cada uma com seus pr\xf3prios erros \u2014 todos\\ncom o campo (`field`) `destinos`, sem \xedndice de item, porque nenhuma \xe9\\numa viola\xe7\xe3o de um \xfanico item isolado. Acumula tamb\xe9m com\\n[`fallback_obrigatorio`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.fallback_obrigatorio),\\n[`excede_limite_de_origens`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_origens)\\ne\\n[`excede_limite_de_destinos`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.excede_limite_de_destinos).\\nNunca coexiste com\\n[`sem_destinos`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.sem_destinos)."],"comoResolver":["Revise a fila de destinos da origem apontada e atribua um valor de `ordem`\\ndistinto a cada posi\xe7\xe3o, sem lacunas nem repeti\xe7\xf5es."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);